// Lossless indexed bitmap. Default API remains one clock.
// Three-clock option: index ROM -> index hold -> palette ROM. The hold
// prevents the index read register being absorbed into the palette address.
module anlogic_logo_rom_sync #(parameter integer PIPELINE_STAGES=1)(
 input wire I_clk,input wire [14:0] I_addr,output wire [24:0] O_pixel);
 generate if(PIPELINE_STAGES==3)begin: indexed

 reg [5:0] first,last;
 reg [12:0] bias;
 wire present=(I_addr[5:0]>=first)&&(I_addr[5:0]<=last);
 wire [12:0] packed_addr=present ? bias+{7'd0,I_addr[5:0]} : 13'd0;
